int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct input_dev *input_dev;
    struct powermate_dev *pdev;
    int error;

    pdev = kzalloc(sizeof(*pdev), GFP_KERNEL);
    if (!pdev)
        return -ENOMEM;

    input_dev = input_allocate_device();
    if (!input_dev) {
        kfree(pdev);
        return -ENOMEM;
    }

    pdev->intf = intf;
    pdev->input_dev = input_dev;

    usb_fill_int_urb(pdev->urb, pdev->udev,
                     usb_rcvintpipe(pdev->udev, pdev->endpoint->bEndpointAddress),
                     pdev->data, sizeof(pdev->data),
                     powermate_irq, pdev, pdev->endpoint->bInterval);

    input_dev->name = "PowerMate";
    input_dev->phys = "usb/input0";
    input_dev->id.bustype = BUS_USB;
    input_dev->dev.parent = &pdev->intf->dev;

    input_set_drvdata(input_dev, pdev);
    usb_set_intfdata(pdev->intf, pdev);

    error = input_register_device(pdev->input_dev);
    if (error) {
        usb_free_urb(pdev->urb);
        input_free_device(pdev->input_dev);
        kfree(pdev);
        return error;
    }

    return 0;
}

int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(intf);
    struct powermate_dev *dev;
    int retval = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        goto error;

    dev->intf = intf;
    dev->udev = udev;

    usb_set_intfdata(intf, dev);

    dev->input_dev = input_allocate_device();
    if (!dev->input_dev)
        goto error_free_dev;

    dev->input_dev->evbit[0] = BIT_MASK(EV_REL) | BIT_MASK(EV_KEY);
    dev->input_dev->keybit[BIT_WORD(BTN_0)] = BIT_MASK(BTN_0);
    dev->input_dev->rel[REL_X] = 0;
    dev->input_dev->name = "PowerMate";
    dev->input_dev->phys = "input/powermate";
    dev->input_dev->id.bustype = BUS_USB;
    dev->input_dev->id.vendor = le16_to_cpu(udev->descriptor.idVendor);
    dev->input_dev->id.product = le16_to_cpu(udev->descriptor.idProduct);
    dev->input_dev->id.version = le16_to_cpu(udev->descriptor.bcdDevice);
    dev->input_dev->dev.parent = &intf->dev;

    if (id->driver_info & PM_USB_ID_2)
        dev->input_dev->name = "Knob";

    if (id->driver_info & PM_USB_ID_2)
        dev->input_dev->phys = "input/knob";

    if (input_register_device(dev->input_dev))
        goto error_free_input_dev;

    dev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->urb)
        goto error_unregister_input_dev;

    usb_fill_int_urb(dev->urb, udev, usb_rcvintpipe(udev, 0x81),
                     dev->data, sizeof(dev->data), powermate_irq, dev, 10);

    dev->urb->transfer_flags |= URB_COPY_DATA;

    if (usb_submit_urb(dev->urb, GFP_KERNEL))
        goto error_free_urb;

    dev->pulse = 0;

    return 0;

error_free_urb:
    usb_free_urb(dev->urb);
error_unregister_input_dev:
    input_unregister_device(dev->input_dev);
error_free_input_dev:
    input_free_device(dev->input_dev);
error_free_dev:
    kfree(dev);
error:
    return retval;
}

int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(intf);
    struct powermate_dev *pdev;
    int ret;

    pdev = kzalloc(sizeof(*pdev), GFP_KERNEL);
    if (!pdev)
        return -ENOMEM;

    pdev->udev = usb_get_dev(udev);
    pdev->intf = intf;

    usb_fill_int_urb(pdev->urb, udev, usb_rcvintpipe(udev, 1),
                     pdev->data, sizeof(pdev->data),
                     powermate_irq, pdev, 10);

    pdev->input_dev = input_allocate_device();
    if (!pdev->input_dev) {
        ret = -ENOMEM;
        goto err_free_dev;
    }

    pdev->input_dev->name = "Powermate";
    pdev->input_dev->id.bustype = BUS_USB;
    pdev->input_dev->id.vendor = le16_to_cpu(udev->descriptor.idVendor);
    pdev->input_dev->id.product = le16_to_cpu(udev->descriptor.idProduct);
    pdev->input_dev->id.version = le16_to_cpu(udev->descriptor.bcdDevice);

    input_set_drvdata(pdev->input_dev, pdev);

    ret = input_register_device(pdev->input_dev);
    if (ret)
        goto err_free_input_dev;

    usb_set_intfdata(intf, pdev);

    return 0;

err_free_input_dev:
    input_free_device(pdev->input_dev);
err_free_dev:
    kfree(pdev);

    return ret;
}

int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(intf);
    struct powermate_dev *pm_dev;
    int retval = -ENOMEM;

    pm_dev = kzalloc(sizeof(*pm_dev), GFP_KERNEL);
    if (!pm_dev)
        goto err_out;

    pm_dev->intf = intf;
    usb_set_intfdata(intf, pm_dev);

    pm_dev->input_dev = input_allocate_device();
    if (!pm_dev->input_dev)
        goto err_free_dev;

    pm_dev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!pm_dev->urb)
        goto err_free_input;

    usb_fill_int_urb(pm_dev->urb, udev, usb_rcvintpipe(udev, 1),
                       pm_dev->data, sizeof(pm_dev->data),
                       powermate_irq, pm_dev, 10);

    pm_dev->urb->transfer_flags |= URB_INTERRUPT;

    pm_dev->input_dev->evbit[0] = BIT_MASK(EV_REL) | BIT_MASK(EV_LED) | BIT_MASK(EV_MSC);
    pm_dev->input_dev->relbit[0] = BIT_MASK(REL_WHEEL);
    pm_dev->input_dev->ledbit[0] = BIT_MASK(LED_MISC);
    pm_dev->input_dev->mscbit[0] = BIT_MASK(MSC_SCAN);

    snprintf(pm_dev->input_dev->name, sizeof(pm_dev->input_dev->name), "Griffin PowerMate");

    input_register_device(pm_dev->input_dev);

    pm_dev->input_dev->users = 1;

    if (id->driver_info & PM_LED_SUPPORT) {
        pm_dev->led_brightness = 0x0f;
        pm_dev->led_pulses = 0;
        pm_dev->led_state = 0;
    }

    return 0;

err_free_input:
    input_free_device(pm_dev->input_dev);
err_free_dev:
    kfree(pm_dev);
err_out:
    return retval;
}

int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct usb_device *udev = usb_interface_to_usbdev(intf);
    struct powermate_dev *pm_dev;
    int error;

    pm_dev = kzalloc(sizeof(*pm_dev), GFP_KERNEL);
    if (!pm_dev)
        return -ENOMEM;

    pm_dev->intf = intf;
    usb_set_intfdata(intf, pm_dev);

    pm_dev->input_dev = input_allocate_device();
    if (!pm_dev->input_dev) {
        error = -ENOMEM;
        goto err_free_dev;
    }

    pm_dev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!pm_dev->urb) {
        error = -ENOMEM;
        goto err_free_input;
    }

    usb_fill_int_urb(pm_dev->urb, udev,
                       usb_rcvintpipe(udev, 1),
                       pm_dev->data, sizeof(pm_dev->data),
                       powermate_irq, pm_dev, 10);

    error = input_register_device(pm_dev->input_dev);
    if (error)
        goto err_free_urb;

    switch (le16_to_cpu(udev->descriptor.idProduct)) {
        case 0x0001:
            strcpy(pm_dev->name, "Griffin PowerMate");
            break;
        default:
            strcpy(pm_dev->name, "Unknown Griffin PowerMate");
            break;
    }

    pm_dev->pulse = 0;
    pm_dev->brightness = 0x0A;

    return 0;

err_free_urb:
    usb_free_urb(pm_dev->urb);
err_free_input:
    input_free_device(pm_dev->input_dev);
err_free_dev:
    kfree(pm_dev);
    return error;
}
